import React from "react"
import { cn } from "@heroui/react"
import type { ReactNode } from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Tooltip } from "@sb-components/atoms/overlay/Tooltip/Tooltip"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import type { ChipTone, IconComponent } from "@sb-components/atoms/chips/Chip/Chip"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `EnumChip` — a `Chip` whose tone / label / optional tooltip / optional leading icon come
 * from a per-value lookup (`map[value]`), so a domain badge shrinks to just its map table plus
 * this delegate. Props: `value`, `map` (two halves of one lookup), `isSkeleton`,
 * `className`/`classNames`.
 */

/**
 * HeroUI soft-chip colors usable by an {@link EnumChip}.
 *
 * Alias, not a redeclaration: the exact same five values `Chip`'s own
 * `ChipTone` already carries.
 *
 * Aliases `ChipTone` specifically (NOT `AlertStatus`): `entry.color` flows
 * straight into `Chip`'s `tone`, a vendor-constrained prop — `ChipTone` is the
 * one guaranteed to match it 1:1.
 */
export type EnumChipColor = ChipTone

/**
 * The ONLY icons an {@link EnumChipEntry} can name — a CLOSED set, not an
 * arbitrary `IconComponent`. A string selector like `ListMark`
 * (`SurfaceCard.tsx`'s own "check"/"cross"/"pending"/"none" vocabulary), NOT
 * a raw icon reference — narrowing to a curated set is the whole point of
 * "universal" symbols (check/cross, nothing caller-chosen). Extend this
 * union the day a THIRD symbol earns the same bar, don't loosen the type.
 */
export type EnumChipIcon = "check" | "cross"

const ENUM_CHIP_ICON_MAP: Record<EnumChipIcon, IconComponent> = {
    check: CheckCircleIcon,
    cross: XCircleIcon,
}

/** One enum value's chip presentation. */
export interface EnumChipEntry {
    /** Soft chip color. Omit to use the Chip default. */
    color?: EnumChipColor
    /** Visible label (already localized by the caller). */
    label: ReactNode
    /** Optional tooltip (already localized); wraps the chip in a Tooltip when set. */
    tooltip?: ReactNode
    /**
     * Optional leading icon — one of {@link EnumChipIcon}, not a component.
     * Omit for every existing map entry that never had one; only add where
     * the value itself is a "universal" symbol, e.g. a failed/not-passed
     * verdict.
     */
    icon?: EnumChipIcon
}

/** Props for {@link EnumChip}. */
export interface EnumChipProps<E extends string> {
    /** The current enum value; looked up in {@link map}. */
    value: E
    /** Map from enum value to presentation (accepts Partial — unhandled values throw). */
    map: Partial<Record<E, EnumChipEntry>>
    /**
     * @deprecated pass `classNames` instead — a free string cannot be constrained.
     * Kept only for the two `_legacy` callers (`HostPlatformChip`, `EntityResultRow`)
     * that still pass a free-form string; `_legacy` is off-limits to edit, so this
     * escape stays until those callers are retired.
     */
    className?: string
    /**
     * Extra classes on the chip. Prefer this over `className`; the string form is going
     * away. This value is handed straight to `Chip`'s own closed `classNames` union, so
     * an unconstrained string here would only fail one tier down.
     */
    classNames?: Array<AllowedClassName>
    /** When `true`, renders the skeleton placeholder (a chip-shaped pill) instead of the real chip. */
    isSkeleton?: boolean
}

/**
 * The canonical "enum → soft chip" composite: a `Chip` whose
 * tone / label / optional tooltip / optional leading icon come from a per-value map.
 * Domain badges (AI-model category, difficulty, video host …) shrink to just their map
 * table + this delegate. Deliberately does NOT force width.
 *
 * Each entry can carry an optional per-value `icon` — most maps stay text-only;
 * a value only gets an icon when it is a "universal" symbol (check/cross), not a habit.
 *
 * @param props - {@link EnumChipProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "EnumChip" } as const

/** Chip whose tone, label, tooltip, and icon come from `map[value]`. */
export const EnumChip = <E extends string>({ value, map, className, classNames, isSkeleton }: EnumChipProps<E>) => {
    const wrapChip = (chip: React.ReactElement) => {
        const cls = cn(className, classNames)
        return cls ? <div className={cls}>{chip}</div> : chip
    }
    if (isSkeleton) {
        // The atom's shimmer matches the real chip box, so no `h-6` patch is needed
        // here — a call site having to patch the atom's shape is the sign the atom is
        // wrong, not this spot. `Chip` no longer takes placement classes; wrap instead.
        return wrapChip(<Chip isSkeleton />)
    }
    const entry = map[value]
    if (!entry) {
        throw new Error(`EnumChip: no map entry for value "${value}"`)
    }
    const chip = wrapChip(
        <Chip
            tone={entry.color ?? "default"}
            text={entry.label}
            icon={entry.icon != null ? ENUM_CHIP_ICON_MAP[entry.icon] : undefined}
        />,
    )
    if (entry.tooltip == null) {
        return chip
    }
    return (
        <Tooltip label={entry.tooltip}>{chip}</Tooltip>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import { ProgressBar } from "@sb-components/atoms/display/Progress/Progress"
import { ProgressMeterTargetMark } from "./TargetMark"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "ProgressMeter" } as const

/** Fill still far from the 85% target — the accent notch pill overshoots the thin bar; `mt-5` reserves room for the floating "85%" label. */
interface ProgressMeterOwnProps {
    /** Maximum value representing 100% completion. Defaults to `100`. */
    max?: number
    /**
     * Optional descriptive label rendered on the left of the top row. Pass a
     * translated string — the block never calls `useTranslations` itself. `string`,
     * not `ReactNode`: the composite wraps it in `Typography` itself, and a
     * pre-built node could not be told it is loading.
     */
    label?: string
    /** When `true`, renders the rounded completion percentage on the right of the top row. */
    showValue?: boolean
    /**
     * Fill color. Defaults to `"accent"`; pass a semantic tone (danger / warning /
     * success) when the bar's VALUE carries meaning.
     */
    color?: "accent" | "success" | "warning" | "danger"
    /** Optional TARGET mark on the track — a thin tick at `target/max` (e.g. an "85% goal" line). */
    target?: number
    /** Optional label rendered above the target tick (e.g. `"85%"`). Only shown when {@link ProgressMeterProps.target} is set. `string` — see {@link ProgressMeterOwnProps.label}. */
    targetLabel?: string
    /**
     * Optional left-aligned COMPONENT slot for a custom row above the track,
     * additive to (and independent of) the `label`/`showValue` row: pass this
     * when the row needs more than plain text (e.g. an icon plus a custom-
     * formatted unit). A COMPONENT reference, not a built node (COMPOSITE-8) —
     * the meter calls it itself and forwards `isSkeleton`, so it can shimmer in
     * place. Omitted (default), no such row renders and existing callers —
     * including ones already using `label`/`showValue` — are unaffected.
     */
    leading?: ComponentTypeWithSkeleton
    /**
     * Right-aligned partner to {@link ProgressMeterOwnProps.leading}. Either
     * may be passed alone; the row renders whichever side(s) are set.
     */
    trailing?: ComponentTypeWithSkeleton
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
    /** Dev/spec: overlay the anatomy annotation on this meter. */
}

/**
 * Props for {@link ProgressMeter}. `value` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer track has no real ratio to show yet.
 */
export type ProgressMeterProps = ProgressMeterOwnProps &
    (
        | { isSkeleton: true; value?: number }
        | { isSkeleton?: false; value: number }
    )

/**
 * ProgressMeter renders a labelled, accessible progress bar: an optional top row
 * (label + rounded percentage) above a house {@link ProgressBar}, with an
 * optional target/goal marker overlaid on the track. A second, independent row
 * — {@link ProgressMeterOwnProps.leading}/{@link ProgressMeterOwnProps.trailing} —
 * can render just above the track for callers that need components instead of
 * plain text.
 *
 * @param props - {@link ProgressMeterProps}
 */
export const ProgressMeter = ({
    value,
    max = 100,
    label,
    showValue = false,
    color = "accent",
    target,
    targetLabel,
    leading: Leading,
    trailing: Trailing,
    isSkeleton = false,
    classNames,
}: ProgressMeterProps) => {
    const safeMax = max > 0 ? max : 1
    // `value` is REQUIRED whenever `isSkeleton` is false (the discriminated union above) —
    // guaranteed by the type at every real call site — the `?? 0` only satisfies narrowing
    // across the destructure, and is never seen while `isSkeleton` (the row it feeds stays
    // unshown or goes through `Typography`'s own shimmer instead).
    const percent = Math.round(((value ?? 0) / safeMax) * 100)
    const hasTopRow = label !== undefined || showValue
    // target tick position, clamped into the track (0..100%)
    const targetPercent = target === undefined
        ? null
        : Math.min(Math.max((target / safeMax) * 100, 0), 100)
    const topRow = hasTopRow ? (
        <StackH
            gap={3}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between"
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="xs" color="muted" truncate isSkeleton={isSkeleton} text={label} />,
                ...(showValue ? [() => (
                    <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={<>{percent}%</>} />
                )] : []),
            ]}
        />
    ) : null
    // Additive row, independent of `topRow` above: a component-based
    // leading/trailing pair for callers that need more than plain text (an
    // icon, a chip, a custom-formatted unit). Either side may be passed alone;
    // omitted entirely, `slotRow` is `null` and nothing changes for existing
    // callers.
    const hasSlotRow = Leading !== undefined || Trailing !== undefined
    const slotRow = hasSlotRow ? (
        <StackH
            gap={3}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between"
            isSkeleton={isSkeleton}
            items={[
                () => Leading ? (
                    <div className="min-w-0">
                        <Leading isSkeleton={isSkeleton} />
                    </div>
                ) : <span />,
                ...(Trailing ? [() => (
                    <div className="shrink-0">
                        <Trailing isSkeleton={isSkeleton} />
                    </div>
                )] : []),
            ]}
        />
    ) : null
    // Two DIFFERENT jobs, so two boxes. A single div doing both — `pt-6` (24px,
    // room for the floating label) and `flex h-5 items-center` (20px, the pill's
    // reference frame) on the SAME element — breaks: padding that exceeds the
    // declared height forces the browser to grow the outer box to fit it (24px,
    // not 20), and the two children then read TWO DIFFERENT origins on that grown
    // box — the track (normal flow) starts AFTER the padding, at y=56, while the
    // pill (`absolute top-1/2`) measures against the WHOLE padding box, landing at
    // y=44.
    // OUTER box owns the label's clearance only (`pt-6`, the scale's first step
    // that clears a `h-5`/20px obstacle).
    // INNER box is `relative flex h-5 items-center` — the pill's containing block
    // AND the track's flex-center axis, both measured against the SAME 20px frame,
    // so the `h-5` pill sits EXACTLY on the track midline.
    const trackSection = (
        <div className={cn(targetPercent !== null && targetLabel !== undefined && "pt-6")}>
            <div
                className={cn(
                    "relative",
                    targetPercent !== null && "flex h-5 items-center",
                )}
            >
                <div className="w-full">
                    <ProgressBar
                        trackDensity="compact"
                        value={value}
                        max={safeMax}
                        color={color}
                        ariaLabel={label ?? "Progress"}
                        isSkeleton={isSkeleton}
                    />
                </div>
                {targetPercent === null ? null : (
                    <ProgressMeterTargetMark percent={targetPercent} label={targetLabel} />
                )}
            </div>
        </div>
    )
    return (
        <StackV
            gap={3}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => topRow,
                () => slotRow,
                () => trackSection,
            ]}
        />
    )
}

import React from "react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "TitledText" } as const

/**
 * `TitledText` — a primary line + optional muted secondary (and optional hint) stacked
 * vertically as one composite; a title<->subtitle pair is a single semantic unit rather than raw
 * `<Typography>` hand-rolled at every row. The composite owns the type scale per `size`; the
 * caller passes nodes only. Leaves: `subtitle`, `hint`, `size`, `weight`, `truncate`, `isSkeleton`.
 */

/**
 * Vertical text-stack scale:
 * - `row`    — dense list/setting row (title `sm` medium · subtitle `xs` muted).
 * - `header` — section/page header (title `h3` semibold · subtitle `sm` muted).
 * - `stat`   — a metric (title = big `h3` bold VALUE · subtitle = foreground label · hint muted).
 */
export type TitledTextSize = "row" | "header" | "stat"

/** Typography `size` + tone config resolved per {@link TitledTextSize}. */
/**
 * Skeleton bar width per line. Named so the widths can be typed where they are WRITTEN, not
 * only where they are read: the classes must be literal (`w-1/2`) because Tailwind only emits
 * a class it can see as a literal string in the source.
 */
interface TitledTextSkeletonWidths {
    /** Width class of the title bar. */
    title: AllowedClassName
    /** Width class of the subtitle bar. */
    sub: AllowedClassName
    /** Width class of the hint bar. */
    hint: AllowedClassName
}

interface SizeConfig {
    titleSize: "sm" | "h3"
    titleWeight: "medium" | "semibold" | "bold"
    subSize: "xs" | "sm"
    /** `undefined` -> foreground (default); `"muted"` -> muted line. */
    subColor?: "muted"
    subWeight?: "medium"
    /**
     * Skeleton bar width for each line — write the class LITERALLY (`w-1/2`), don't
     * build it dynamically (`w-${…}`), since Tailwind only generates a class from a
     * literal string it scans in the source.
     */
    skeleton: TitledTextSkeletonWidths
}

const SIZE_CONFIG: Record<TitledTextSize, SizeConfig> = {
    row: {
        titleSize: "sm",
        titleWeight: "medium",
        subSize: "xs",
        subColor: "muted",
        skeleton: { title: "w-1/2", sub: "w-2/3", hint: "w-1/3" },
    },
    header: {
        titleSize: "h3",
        titleWeight: "semibold",
        subSize: "sm",
        subColor: "muted",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" },
    },
    stat: {
        titleSize: "h3",
        titleWeight: "bold",
        // stat's secondary is the LABEL — foreground + medium, not muted.
        subSize: "sm",
        subWeight: "medium",
        skeleton: { title: "w-1/3", sub: "w-2/3", hint: "w-1/2" },
    },
}

/** Props for the {@link TitledText} composite. */
export interface TitledTextProps {
    /** Primary line (title / name / label / stat value), rendered through `Typography`. */
    title: string
    /** Optional secondary line beneath the title (subtitle / role / description / stat label). */
    subtitle?: string
    /** Optional third muted line (only meaningful for `size="stat"`, e.g. a delta hint). */
    hint?: string
    /** Text-stack scale. Defaults to `"row"`. */
    size?: TitledTextSize
    /** Override the title weight (per-size default otherwise). */
    weight?: "medium" | "semibold" | "bold"
    /** Truncate every line to a single line (needs a bounded parent width). */
    truncate?: boolean
    /** `true` -> render the skeleton mirror (bars sized per line). */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * TitledText renders a primary line over an optional muted secondary (and hint)
 * as one vertical unit. The composite OWNS the type scale + tone per `size`; the
 * caller passes nodes only. Root is `flex min-w-0 flex-col` so truncation works
 * and callers can add `flex-1`.
 *
 * @param props - {@link TitledTextProps}
 */
export const TitledText = ({
    title,
    subtitle,
    hint,
    size = "row",
    weight,
    truncate = false,
    isSkeleton = false,
    classNames,
}: TitledTextProps) => {
    const cfg = SIZE_CONFIG[size]
    const rootClassNames: Array<AllowedClassName> = ["min-w-0", ...(classNames ?? [])]

    // COMPOSITE-10: ONE render path — same `StackV`, same `gap`, in both states.
    // Text always goes through the `Typography` ATOM; `isSkeleton` just flows
    // straight into it so each line draws its own bar, sized to its own value
    // (§12c) — no second, hand-built skeleton tree to keep in sync with this one.
    return (
        <StackV
            gap={1}
            classNames={rootClassNames}
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <Typography
                        size={cfg.titleSize}
                        weight={isSkeleton ? undefined : (weight ?? cfg.titleWeight)}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={title}

                    />
                ),
                ...(subtitle ? [() => (
                    <Typography
                        size={cfg.subSize}
                        color={isSkeleton ? undefined : cfg.subColor}
                        weight={isSkeleton ? undefined : cfg.subWeight}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={subtitle}

                    />
                )] : []),
                ...(hint ? [() => (
                    <Typography
                        size="xs"
                        color={isSkeleton ? undefined : "muted"}
                        truncate={isSkeleton ? undefined : truncate}
                        isSkeleton={isSkeleton}
                        text={hint}

                    />
                )] : []),
            ]}
        />
    )
}

"use client"

import React, { useState } from "react"
import { CodeIcon, SidebarIcon } from "@phosphor-icons/react"
import {
    TabsExtended,
    TabsIndicator,
    TabsList,
    TabsListContainer,
    TabsTab,
} from "@sb-components/atoms/navigation/Tabs/Tabs"
import { StackV } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — faithful port of
 * `@/components/blocks/rendering/MarkdownContent/CodePreviewTabs`. Authored in
 * Storybook (not `src`); synced back to `src` later.
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props for {@link CodePreviewTabs}. */
export interface CodePreviewTabsProps {
    /** Live render (the rendered demo pane). */
    preview: React.ReactNode
    /** Source code panel (Shiki-highlighted). */
    code: React.ReactNode
    /** Where this sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Presentational **[ Preview | Code ]** tabs, self-contained (`TabsExtended`
 * atom root + house tab parts + phosphor icons). Preview is selected first so
 * the learner sees the rendered result, then flips to the code. Shared by
 * `TabsBlock` (the `:::tab` directive's dual panes) so the tab shell stays
 * identical and depends on NO layout component.
 * @param props - {@link CodePreviewTabsProps}
 */
export const CodePreviewTabs = ({ preview, code, classNames }: CodePreviewTabsProps) => {
    const [tab, setTab] = useState<"preview" | "code">("preview")
    const panes = [
        () => (
            <TabsExtended
                selectedKey={tab}
                variant="secondary"
                onSelectionChange={(key) => setTab(key === "code" ? "code" : "preview")}
            >
                <TabsListContainer className="w-fit">
                    <TabsList aria-label="Preview / Code" className="w-fit">
                        <TabsTab
                            id="preview"
                            data-principle="icon-text" className="gap-1 data-[selected=true]:text-accent-soft-foreground"
                        >
                            <SidebarIcon />
                            Preview
                            <TabsIndicator />
                        </TabsTab>
                        <TabsTab
                            id="code"
                            data-principle="icon-text" className="gap-1 data-[selected=true]:text-accent-soft-foreground"
                        >
                            <CodeIcon />
                            Code
                            <TabsIndicator />
                        </TabsTab>
                    </TabsList>
                </TabsListContainer>
            </TabsExtended>
        ),
        () => (
            <div className={tab === "preview" ? "rounded-xl border border-divider p-3" : undefined}>
                {tab === "preview" ? preview : code}
            </div>
        ),
    ]
    return (
        <StackV
            gap={3}
            classNames={classNames}
            items={panes}
        />
    )
}

import React, { useEffect, useMemo, useRef, useState } from "react"
import ReactMarkdown from "react-markdown"
import remarkDirective from "remark-directive"
import remarkGfm from "remark-gfm"
import { cn } from "@heroui/react"
import { buildMarkdownRenderers } from "@sb-components/composites/viewers/MarkdownContent/map"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `MarkdownContent` — a viewer that paints an authored markdown document faithfully. Unlike
 * other composites it cannot know its shape before rendering — the payload decides it. Handles
 * Shiki-highlighted fenced code, mermaid diagrams (click-to-zoom, caption pairing),
 * `:::tab`/`:::code`/`:::preview` -> Preview<->Code tabs, GFM tables -> HeroUI `Table`,
 * `::::accordion`/`:::panel` -> HeroUI `Accordion`, plus `:::muted`/`:::chip`, image captions,
 * link routing, and heading anchors. Leaves by structure are the two spacing measures.
 */

/** How much room the document gets. */
export type MarkdownMeasure = "reading" | "compact"

/**
 * A directive node as `remark-directive` parses it — shared shape for the
 * `:::muted` / `:::tab`/`:::code`/`:::preview` / `::::accordion`/`:::panel`
 * rewriters below (they all only ever read/write these same four fields).
 */
interface DirectiveNode {
    /** mdast node type (`"containerDirective"` / `"leafDirective"` / `"textDirective"` for a directive). */
    type?: string
    /** Directive name as authored (`"muted"`, `"tab"`, `"code"`, `"preview"`, `"chip"`, `"accordion"`, `"panel"`). */
    name?: string
    /** Directive attributes (`{title="…"}`). */
    attributes?: Record<string, string>
    /** hast rewrite instructions (`hName`/`hProperties`) this pass writes into. */
    data?: Record<string, unknown>
    /** Child mdast nodes. */
    children?: Array<unknown>
}

/** A directive's inline content node, as read by {@link collectDirectiveText}. */
interface DirectiveTextNode {
    /** mdast node type (`"text"`, `"break"`, or a container). */
    type?: string
    /** Text value (only on `"text"` nodes). */
    value?: string
    /** Child mdast nodes. */
    children?: Array<unknown>
}

/**
 * Recursively rewrites `:::muted` directives (container/leaf/text, parsed by `remark-directive`)
 * into custom hast tags the renderer map styles as small muted text. Container/leaf -> block-level
 * `mutedblock`; inline `:muted[…]` -> `mutedtext`. Directives with any other name are left untouched
 * (and dropped by the hast conversion since they have no handler).
 * @param node - Current mdast node being walked.
 */
const applyMutedDirective = (node: DirectiveNode): void => {
    if (
        (node.type === "containerDirective" || node.type === "leafDirective" || node.type === "textDirective")
        && node.name === "muted"
    ) {
        const data = node.data || (node.data = {})
        data.hName = node.type === "textDirective" ? "mutedtext" : "mutedblock"
        data.hProperties = {}
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyMutedDirective(child as DirectiveNode)
        }
    }
}

/** remark transformer: turn `:::muted` directives into styled custom tags. */
const remarkMuted = () => (tree: unknown): void => {
    applyMutedDirective(tree as DirectiveNode)
}

/**
 * Recursively rewrites the `:::tab` / `:::code` / `:::preview` container directives into custom
 * hast tags the renderer map turns into a [Preview|Code] tabs block (see `TabsBlock`):
 * `tab`->`tabblock`, `code`->`tabcode`, `preview`->`tabpreview`. Each pane's child fence
 * (` ```tsx ` / ` ```mdx `) still renders through the normal `pre` handler. Other directive names
 * are left untouched.
 *
 * Note: container nesting needs MORE colons on the outer fence — `::::tab` wraps `:::code` /
 * `:::preview`.
 * @param node - Current mdast node being walked.
 */
const applyTabDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective") {
        const tag = node.name === "tab"
            ? "tabblock"
            : node.name === "code"
                ? "tabcode"
                : node.name === "preview"
                    ? "tabpreview"
                    : null
        if (tag) {
            const data = node.data || (node.data = {})
            data.hName = tag
            data.hProperties = {}
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyTabDirective(child as DirectiveNode)
        }
    }
}

/** remark transformer: turn `::::tab`/`:::code`/`:::preview` directives into tabs-block tags. */
const remarkTab = () => (tree: unknown): void => {
    applyTabDirective(tree as DirectiveNode)
}

/**
 * Recursively collects the raw text of a directive subtree, preserving line breaks so each
 * authored line (one keyword per line) can be split back out into a separate chip.
 * @param node - Current mdast node.
 */
const collectDirectiveText = (node: DirectiveTextNode): string => {
    if (node.type === "text") {
        return node.value ?? ""
    }
    if (node.type === "break") {
        return "\n"
    }
    if (Array.isArray(node.children)) {
        return node.children
            .map((child) => collectDirectiveText(child as DirectiveTextNode))
            .join("\n")
    }
    return ""
}

/**
 * Rewrites the `:::chip` container directive into a custom `chipblock` tag (see `map.tsx`),
 * carrying its keywords (one per authored line) as a newline-split, `|`-joined `items` prop so the
 * renderer can render each as its own Chip. Other directive names are left untouched.
 * @param node - Current mdast node being walked.
 */
const applyChipDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective" && node.name === "chip") {
        const items = collectDirectiveText(node as DirectiveTextNode)
            .split(/[\n·]+/)
            .map((line) => line.trim())
            .filter((line) => line.length > 0)
        const data = node.data || (node.data = {})
        data.hName = "chipblock"
        data.hProperties = {
            items: items.join("|"),
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyChipDirective(child as DirectiveNode)
        }
    }
}

/** remark transformer: turn `:::chip` directives into a chips-row tag. */
const remarkChip = () => (tree: unknown): void => {
    applyChipDirective(tree as DirectiveNode)
}

/**
 * Rewrites the `::::accordion` / `:::panel{title="…"}` container directives into custom hast tags
 * the renderer map turns into a HeroUI Accordion (see `map.tsx`): `accordion`->`accordionblock`;
 * each `:::panel{title="…"}`->`accordionpanel` carrying its `title` attribute. Inner panel content
 * (bullets, code fences) still renders through the normal handlers.
 *
 * Note: nesting needs MORE colons on the outer fence — `::::accordion` wraps `:::panel`.
 * @param node - Current mdast node being walked.
 */
const applyAccordionDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective") {
        if (node.name === "accordion") {
            const data = node.data || (node.data = {})
            data.hName = "accordionblock"
            data.hProperties = {}
        } else if (node.name === "panel") {
            const data = node.data || (node.data = {})
            data.hName = "accordionpanel"
            data.hProperties = { title: node.attributes?.title ?? "" }
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) applyAccordionDirective(child as DirectiveNode)
    }
}

/** remark transformer: `::::accordion`/`:::panel` become accordion tags. */
const remarkAccordion = () => (tree: unknown): void => {
    applyAccordionDirective(tree as DirectiveNode)
}

/**
 * Module-level constant — NOT recreated every render. If `remarkPlugins={[...]}` were inline, each
 * `MarkdownContent` re-render would hand `ReactMarkdown` a new array -> re-parse the whole markdown.
 */
const REMARK_PLUGINS = [remarkGfm, remarkDirective, remarkMuted, remarkTab, remarkChip, remarkAccordion]

// Matches each ```mermaid fence and the figure caption paragraph that follows it.
// Group 1 = diagram source; group 2 = the first non-blank line after the fence.
const MERMAID_CAPTION_REGEX = /```mermaid[ \t]*\r?\n([\s\S]*?)\r?\n```[ \t]*\r?\n+[ \t]*([^\r\n]+)/g

/**
 * Cuts off a trailing ```mermaid fence that hasn't been closed yet — markdown fed in
 * progressively (a typewriter reveal, an AI stream) walks THROUGH every partial length of the
 * diagram source one tick at a time, and `mermaid.render()` throws "Syntax error in text" for
 * every one of those incomplete snapshots. Since a reveal only ever GROWS the text, at most the
 * LAST fence can be unterminated — any earlier one already has content (and therefore its closing
 * fence) after it.
 * @param markdown - Raw markdown source, possibly mid-reveal.
 * @returns `markdown` unchanged, or truncated right before an unterminated trailing mermaid fence.
 */
const holdBackIncompleteMermaidFence = (markdown: string): string => {
    const lines = markdown.split("\n")
    let lastOpenLine = -1
    for (let i = 0; i < lines.length; i++) {
        if (/^```mermaid[ \t]*$/.test(lines[i].trimEnd())) {
            lastOpenLine = i
        }
    }
    if (lastOpenLine === -1) {
        return markdown
    }
    const isClosed = lines.slice(lastOpenLine + 1).some((line) => line.trim() === "```")
    return isClosed ? markdown : lines.slice(0, lastOpenLine).join("\n").trimEnd()
}

/**
 * Scans markdown for mermaid blocks and pairs each with the caption paragraph that
 * immediately follows it (a figure-caption line, Vietnamese or English — see the regex below), keyed by trimmed source.
 * @param markdown - Raw markdown source.
 * @returns Caption text keyed by trimmed mermaid source.
 */
const extractMermaidCaptions = (markdown: string): Record<string, string> => {
    const captions: Record<string, string> = {}
    MERMAID_CAPTION_REGEX.lastIndex = 0
    for (let match = MERMAID_CAPTION_REGEX.exec(markdown); match; match = MERMAID_CAPTION_REGEX.exec(markdown)) {
        const code = match[1].trim()
        const caption = match[2].trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(caption)) { // vn-ok: matches the VI figure word in lesson prose
            captions[code] = caption
        }
    }
    return captions
}

/**
 * Removes each mermaid figure-caption paragraph ("Figure N: …", either language) from the source
 * so it isn't rendered twice — the diagram now shows it as a real `<figcaption>`.
 * @param markdown - Raw markdown source.
 * @returns Markdown with figure-caption paragraphs stripped.
 */
const stripMermaidCaptions = (markdown: string): string => {
    MERMAID_CAPTION_REGEX.lastIndex = 0
    return markdown.replace(MERMAID_CAPTION_REGEX, (match: string, _code: string, caption: string) => {
        const clean = caption.trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(clean)) { // vn-ok: matches the VI figure word in lesson prose
            return match.slice(0, match.lastIndexOf(caption))
        }
        return match
    })
}

/**
 * Storybook has no `next-themes` provider (unlike `src`) — the toolbar's Light/Dark
 * global instead stamps a `"light"`/`"dark"` class on an ANCESTOR wrapper div (see
 * `.storybook/preview.tsx`). Read it off the DOM the same way `BlockAnatomy` already
 * does (`host.closest(".dark")`), and keep it live with a `MutationObserver` so
 * flipping the toolbar mid-session re-themes Mermaid/Shiki without a remount.
 * @param ref - Ref on (or inside) the element whose nearest themed ancestor to watch.
 */
const useIsDarkTheme = (ref: React.RefObject<HTMLDivElement | null>): boolean => {
    const [isDark, setIsDark] = useState(false)
    useEffect(() => {
        const el = ref.current
        if (!el) {
            return
        }
        const themeHost = el.closest(".light, .dark") ?? document.documentElement
        const read = () => setIsDark(themeHost.classList.contains("dark"))
        read()
        const observer = new MutationObserver(read)
        observer.observe(themeHost, { attributes: true, attributeFilter: ["class"] })
        return () => observer.disconnect()
    }, [ref])
    return isDark
}

/** Props for {@link MarkdownContent}. */
export interface MarkdownContentProps {
    /** The document, as authored. This is the payload that decides the shape. */
    source: string
    /** How much room the document gets. Defaults to `"reading"`. */
    measure?: MarkdownMeasure
    /** Where the article wrapper sits inside its parent, from the closed positioning union. */
    classNames?: Array<AllowedClassName>
    /**
     * `true` -> render a 2-line shimmer mirror instead of the real document
     * (the owner of the shape owns the skeleton).
     */
    isSkeleton?: boolean
}

/**
 * Render an authored markdown document. See the file header for the scope of
 * this port and why a viewer is allowed to write its own spacing.
 *
 * @param props - {@link MarkdownContentProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "MarkdownContent" } as const

const MarkdownContent = ({
    source,
    measure = "reading",
    classNames,
    isSkeleton = false,
}: MarkdownContentProps) => {
    const reading = measure === "reading"
    const rootRef = useRef<HTMLDivElement>(null)
    const isDark = useIsDarkTheme(rootRef)

    // Hold back an unterminated trailing mermaid fence FIRST — see the helper's own JSDoc.
    // Hooks run UNCONDITIONALLY even on a skeleton call (rules of hooks) — `source` is
    // just "" on that path (see the call-site), so this is cheap, not wasted real work.
    const stableSource = useMemo(() => holdBackIncompleteMermaidFence(source), [source])
    const mermaidCaptions = useMemo(() => extractMermaidCaptions(stableSource), [stableSource])
    // Strip mermaid figure-captions — they render as a real `<figcaption>` instead.
    const renderedSource = useMemo(() => stripMermaidCaptions(stableSource), [stableSource])

    const components = useMemo(
        () => buildMarkdownRenderers({ isDark, reading, mermaidCaptions }),
        [isDark, reading, mermaidCaptions],
    )

    // Skeleton mirror owned by THIS composite (§12c) — AFTER every hook above has run
    // (rules of hooks: an early return before a hook call would skip it conditionally).
    if (isSkeleton) {
        return (
            <StackV
                gap={3}
                classNames={classNames}
                isSkeleton={isSkeleton}

                items={[
                    () => <Typography isSkeleton size="base" />,
                    () => <Typography isSkeleton size="base" />,
                ]}
            />
        )
    }

    return (
        <article
            ref={rootRef}

            className={cn("first:*:mt-0 last:*:mb-0")}
            data-tier="composite"
            data-component="MarkdownContent"
        >
            <ReactMarkdown remarkPlugins={REMARK_PLUGINS} components={components as never}>
                {renderedSource}
            </ReactMarkdown>
        </article>
    )
}

export { MarkdownContent }

import React from "react"
import { cn } from "@heroui/react"
import {
    AccordionTree,
    AccordionTreeBody,
    AccordionTreeHeading,
    AccordionTreeIndicator,
    AccordionTreeItem,
    AccordionTreePanel,
    AccordionTreeTrigger,
} from "@sb-components/atoms/navigation/AccordionTree/AccordionTree"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { CodeToHtml } from "@sb-components/composites/viewers/MarkdownContent/CodeToHtml"
import { MermaidDiagram } from "@sb-components/composites/viewers/MarkdownContent/MermaidDiagram"
import { TabsBlock, TabPane } from "@sb-components/composites/viewers/MarkdownContent/TabsBlock"
import {
    MarkdownTable,
    MarkdownTableBody,
    MarkdownTableCell,
    MarkdownTableColumn,
    MarkdownTableHead,
    MarkdownTableRow,
} from "@sb-components/composites/viewers/MarkdownContent/MarkdownTableParts"
import { Box } from "@sb-components/frames/Box/Box"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * The element-renderer MAP for `MarkdownContent` — the whole grammar (headings,
 * tables, code, mermaid, custom directive tags) in one file.
 *
 * Handles: Shiki syntax highlighting, mermaid diagrams, `:::tab`/`:::code`/
 * `:::preview` -> Preview<->Code tabs, GFM tables -> house `TableRoot`,
 * `::::accordion`/`:::panel` -> house `AccordionTree`, `:::muted`, `:::chip`, image
 * captions, link routing, heading anchors. Not handled here: `arcSections`,
 * `plain` mode, the ` ```mdx ` live-render fence, the ` ```layout ` fence.
 *
 * Vertical rhythm is owned by the single wrapper in `MarkdownContent.tsx`, or in
 * reading measure by a plain `<div className={blockMy}>` around each block-level
 * renderer's output — margin is a seam between two blocks, written where both are
 * visible rather than passed as a `className` prop. `CodeToHtml`,
 * `MermaidDiagram`, and `MarkdownTable` take no `className`.
 */

/** UI copy for the code/table/mermaid chrome. Storybook has no i18n-aware runtime
 * for this tree (see the file header on `MarkdownContent.tsx`), so — like every
 * other composite in this design system — the copy is a hardcoded constant
 * instead of a `useTranslations()` call. Values mirror `src/messages/vi.json`'s
 * `markdown.*` keys so a reader comparing the two sees the same words. */
const TABLE_ARIA_LABEL = "Content table"
const MERMAID_LOADING_LABEL = "Drawing diagram..."
const MERMAID_EXPAND_LABEL = "Expand diagram"
const MERMAID_FALLBACK_LABEL = "Figure"
const HEADING_ANCHOR_LABEL = "Link to this section"

/** Anything the parser hands back with only children — most of the grammar. */
export interface MarkdownNodeProps {
    /** Whatever the parser put inside this element. */
    children?: React.ReactNode
}

/** A link node: the payload decides the target, the viewer only decides the skin. */
export interface MarkdownLinkProps extends MarkdownNodeProps {
    /** Link target as authored. */
    href?: string
}

/** An image node — a raw URL plus its alt text, both straight from the payload. */
export interface MarkdownImageProps {
    /** Image source as authored. */
    src?: string
    /** Alt text as authored; a non-empty alt doubles as a real figure caption. */
    alt?: string
}

/**
 * A code node. A fenced block arrives with `language-*` on react-markdown's
 * `className`; that string is the language hook, not a styling door — stored here
 * as `fenceClass` so COMPOSITE-4 does not see a `className` prop on a `*Props` type.
 */
export interface MarkdownCodeProps extends MarkdownNodeProps {
    /** `language-*` for a fenced block, absent for inline code. */
    fenceClass?: string
}

/** react-markdown still emits `className` on `code`; rename at the renderer boundary. */
type MarkdownCodeRuntimeProps = MarkdownNodeProps & {
    className?: string
}

/** One `:::panel{title="…"}` inside an `::::accordion` block. */
export interface MarkdownPanelProps extends MarkdownNodeProps {
    /** Trigger-row title carried by the directive attribute. */
    title?: string
}

/** The `:::chip` directive's rewritten tag — one `|`-joined line of keywords. */
export interface MarkdownChipBlockProps {
    /** `|`-joined keyword list, one per authored line (see `remarkChip` in `MarkdownContent.tsx`). */
    items?: string
}

/** Config for one {@link buildTocHeading} level. */
interface TocHeadingConfig {
    /** Heading depth surfaced in the outline. */
    level: 2 | 3 | 4
    /** Tailwind text-size class. */
    sizeClass: string
    /** Tailwind margin class (asymmetric — reading measure only). */
    marginClass: string
    /** `true` (reading measure only) -> render the hover `#` deep-link affordance. */
    showAnchor: boolean
}

/**
 * Recursively flattens a React children tree to its plain-text content — used to
 * derive a stable heading slug (and the "on this page" outline label) from the
 * rendered heading nodes.
 * @param node - The React node to read text from.
 * @returns The concatenated text content.
 */
const getNodeText = (node: React.ReactNode): string => {
    if (node === null || node === undefined || typeof node === "boolean") {
        return ""
    }
    if (typeof node === "string" || typeof node === "number") {
        return String(node)
    }
    if (Array.isArray(node)) {
        return node.map(getNodeText).join("")
    }
    if (React.isValidElement(node)) {
        return getNodeText((node.props as MarkdownNodeProps).children)
    }
    return ""
}

/**
 * Slugify heading text into a URL-safe anchor id (diacritics stripped, Vietnamese
 * Vietnamese d-with-stroke folded to `d`, non-alphanumerics collapsed to single hyphens). Deterministic so the
 * rendered heading id and any "on this page" outline reading it from the DOM agree.
 * @param text - The raw heading text.
 * @returns The anchor slug.
 */
const slugify = (text: string): string =>
    text
        .normalize("NFKD")
        .replace(/[̀-ͯ]/g, "")
        .replace(/[đĐ]/g, "d") // vn-ok: slug transliteration of the VI letter
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")

/**
 * Heading renderer factory: renders a section heading carrying a slug `id` +
 * `data-toc` markers so an "on this page" rail can scan the rendered article
 * (`[data-toc]`) and anchor-scroll to it. `scroll-mt-20` clears a sticky navbar
 * when jumped to. The hover `#` deep-link only renders in reading measure — cards
 * / chat / modals have no shareable url for it.
 * @param config - {@link TocHeadingConfig}
 */
const buildTocHeading = ({ level, sizeClass, marginClass, showAnchor }: TocHeadingConfig) =>
    ({ children }: MarkdownNodeProps) => {
        const Tag = `h${level}` as "h2" | "h3" | "h4"
        const text = getNodeText(children)
        const id = slugify(text)
        return (
            <Tag
                id={id}
                data-toc=""
                data-toc-level={level}
                data-toc-label={text}
                className={cn("group scroll-mt-20 font-semibold", marginClass, sizeClass)}
            >
                {children}
                {showAnchor ? (
                    <a
                        href={`#${id}`}
                        aria-label={HEADING_ANCHOR_LABEL}
                        className="ml-2 text-muted no-underline opacity-0 transition-opacity group-hover:opacity-100"
                    >
                        #
                    </a>
                ) : null}
            </Tag>
        )
    }

/** Params for {@link buildMarkdownRenderers}. */
export interface MarkdownRenderersParams {
    /** True when the Storybook toolbar theme is dark; selects mermaid/Shiki themes. */
    isDark: boolean
    /** Reading-grade typography (bigger type, generous rhythm) vs the compact scale. */
    reading: boolean
    /** Figure captions keyed by trimmed mermaid source, paired from the following paragraph. */
    mermaidCaptions: Record<string, string>
}

/**
 * Builds the element-renderer map handed to `ReactMarkdown`. See the file header
 * for scope; each renderer stays margin-free in compact measure (the wrapper in
 * `MarkdownContent.tsx` owns the uniform rhythm there) and carries its own
 * asymmetric margin in reading measure.
 * @param params - {@link MarkdownRenderersParams}
 */
export const buildMarkdownRenderers = ({ isDark, reading, mermaidCaptions }: MarkdownRenderersParams) => {
    const blockMy = reading ? "my-4" : "my-3"
    // Link text rides the same body scale as the surrounding prose.
    const linkSize = reading ? "base" : "sm"

    return {
        h1: ({ children }: MarkdownNodeProps) => (
            <h1 className={cn("font-semibold text-foreground", reading ? "mt-8 mb-3 text-2xl" : "mt-6 mb-2 text-xl")}>{children}</h1>
        ),
